    {
      "name": "Finsupp.weight_single",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (s : σ) (r : R), (Finsupp.weight w) (Finsupp.single s r) = r • w s"
    },
    {
      "name": "Finsupp.weight_single_index",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  [inst_3 : DecidableEq σ] (s : σ) (c : M) (f : σ →₀ R), (Finsupp.weight (Pi.single s c)) f = f s • c"
    },
    {
      "name": "Finsupp.smul_single_one",
      "module_name": "Mathlib.Data.Finsupp.SMul",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_6} [inst : MulZeroOneClass R] (a : α) (b : R), b • Finsupp.single a 1 = Finsupp.single a b"
    },
    {
      "name": "Finsupp.smul_single'",
      "module_name": "Mathlib.Data.Finsupp.SMul",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {R : Type u_6} {x : Semiring R} (c : R) (a : α) (b : R),\n  c • Finsupp.single a b = Finsupp.single a (c * b)"
    },
    {
      "name": "Finsupp.smul_single",
      "module_name": "Mathlib.Data.Finsupp.SMulWithZero",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} {R : Type u_11} [inst : Zero M] [inst_1 : SMulZeroClass R M] (c : R) (a : α) (b : M),\n  c • Finsupp.single a b = Finsupp.single a (c • b)"
    },
    {
      "name": "DFinsupp.nsmul_apply",
      "module_name": "Mathlib.Data.DFinsupp.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : (i : ι) → AddMonoid (β i)] (b : ℕ) (v : Π₀ (i : ι), β i) (i : ι),\n  (b • v) i = b • v i"
    }
  ]
}
